    build(u << 1, l, mid);
    build(u << 1 | 1, mid + 1, r);
    mx[u] = max(mx[u << 1], mx[u << 1 | 1]);
}

ll query(int u, int l, int r, int x, int y) {
    if (x <= l && r <= y) return mx[u];
    int mid = (l + r) >> 1;
    ll res = V;
    if (x <= mid) res = max(res, query(u << 1, l, mid, x, y));
    if (y > mid) res = max(res, query(u << 1 | 1, mid + 1, r, x, y));
